    var blocks = blocksIn(kids).filter(function (b) {
      return words(textOf(b)) > 0;
    });
    if (!blocks.length) return [];
    var total = stats(blocks).words;
    var target = total / Math.min(CP_GROUPS, blocks.length);
    var groups = [];
    var cur = [],
      acc = 0;
    blocks.forEach(function (b, i) {
      cur.push(b);
      acc += words(textOf(b));
      var left = blocks.length - i - 1;
      if (acc >= target * (groups.length + 1) && left > 0 || left === 0) {
        groups.push(cur);
        cur = [];
      }
    });
    return groups.map(function (g, i) {
      var s = stats(g);
      s.el = g[0];
      s.focus = g[0];
      s.name = 'Part ' + (i + 1) + ' of ' + groups.length;
      return s;
    });
